update public.products set description='Honey beans, locally known as Ewa Oloyin, are a Nigerian cowpea type with a naturally mild, slightly sweet flavour and soft texture when properly cooked, suitable for beans porridge, rice and beans, Moi Moi and Akara.', handling_protocols=array['Sort carefully and remove stones, foreign matter, damaged seeds and insects.','Rinse thoroughly in clean water; soaking may be used to reduce cooking time.','Cook thoroughly until the beans are completely tender.']::text[], storage_tips=array['Store completely dry in an airtight or hermetic food-safe container away from moisture, heat and direct sunlight.','Protect bulk quantities from cowpea storage beetles with suitable hermetic storage.','For best quality, use within about 6–12 months when properly dried and sealed.','Discard beans that become moldy, damp or musty-smelling, severely insect-damaged or unusually off-smelling.']::text[] where name='Maiduguri Honey Beans (Oloyin)' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Dry soya beans are protein-rich oilseed legumes used in foods such as soy milk, tofu-style products, soy flour, blended cereals and other cooked or processed meals.', handling_protocols=array['Sort before processing and remove stones, damaged beans and foreign material.','Rinse thoroughly and soak when appropriate for the intended recipe.','Do not consume raw soya beans; apply adequate heat during preparation or processing.']::text[], storage_tips=array['Keep dry soybeans in a clean airtight or hermetic container in a cool, dry and dark location.','Prevent moisture from entering the container and protect from heat, insects and rodents.','For best quality, use within about 6–12 months when dry and sealed.','Discard beans that become moldy, damp, fermented or musty-smelling, heavily infested or noticeably rancid.']::text[] where name='Soya Beans' and category_id=(select id from public.product_categories where name='Tubers & Legumes');;
